using Aspire.Hosting.Testing;

namespace MyApp.Evaluation;

public sealed class AppHostFixture : IAsyncLifetime
{
    public DistributedApplication App { get; private set; } = default!;

    public async ValueTask InitializeAsync()
    {
        var builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        App = await builder.BuildAsync();
        await App.StartAsync();
    }

    public async ValueTask DisposeAsync()
    {
        await App.DisposeAsync();
    }
}

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static readonly AppHostFixture _fixture = new();

    [ClassInitialize]
    public static async Task Setup(TestContext _) => await _fixture.InitializeAsync();

    [ClassCleanup]
    public static async Task Teardown() => await _fixture.DisposeAsync();

    [TestMethod]
    public async Task AppHost_StartsSuccessfully()
    {
        // Verify the distributed application started without errors.
        Assert.IsNotNull(_fixture.App);
        await Task.CompletedTask;
    }

    [TestMethod]
    public async Task AppHost_ResourcesAreRunning()
    {
        var app = _fixture.App;

        // Wait briefly for resources to enter a running state.
        using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(30));
        await app.ResourceNotifications.WaitForResourceHealthyAsync(
            "webfrontend", cts.Token).WaitAsync(cts.Token).ConfigureAwait(false);
    }
}

